package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 * the number null unless it has one, the due fixed at settling (two decimals) or null while it is live,
 * the user who opened it or null while it is a draft, whether a statement bound it and the figure it bound
 * it to (two decimals; null: n/a), and the number of the claim a correction corrects (null: not a correction), and its due-by fixed when it was created (yyyy-MM-dd), and its status log, oldest first, and the date it is deferred until (yyyy-MM-dd; null: never deferred), and how many proofs it has been given, and the number of the claim it was split off (null: none), and the user whose open editor locks it (null: not locked), and whether it is a late entry (added while its period was soft-closed), and the last day it was reminded (yyyy-MM-dd; null: never), and its external reference (null: none), and its tags, sorted (none: empty), and the reason it was voided with (null: none), and its comments, oldest first, and the number of the bulk settle batch that settled it (null: none), and its lines, in the order added, and when it was added (on the sequence rates are saved on: see the rate's saved). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        List<LogLine> log, String deferredUntil, int proofs, String splitFrom, String lockedBy,
        boolean lateEntry, String reminded, String ref, List<String> tags, String voidReason,
        List<Comment> comments, Integer batch, List<Line> lines, long added) {

    /** A line of the status log: the status, the user who gave it, the sheet's today then and the due then. */
    public record LogLine(String status, String by, String date, String due) {
    }

    /** A comment: the user who wrote it, the sheet's today then and its text. */
    public record Comment(String by, String date, String text) {
    }

    /** A line: its label, its quantity and its unit amount (two decimals). */
    public record Line(String label, int qty, String unit) {
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log) {
        return from(claim, log, null, false, null, null, null, null, List.of(), null, List.of());
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log, String lockedBy, boolean lateEntry,
            LocalDate reminded, String ref, String tags, String voidReason, List<ClaimComment> comments,
            Integer batch, List<ClaimLine> lines) {
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().setScale(2).toPlainString(), claim.openedBy(),
                claim.stated(), claim.statedDue() == null ? null : claim.statedDue().setScale(2).toPlainString(),
                claim.corrects(), claim.dueBy().toString(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(),
                claim.proofs(), claim.splitFrom(), lockedBy, lateEntry,
                reminded == null ? null : reminded.toString(), ref,
                tags == null ? List.of() : List.of(tags.split(",")), voidReason,
                comments.stream().map((c) -> new Comment(c.by(), c.date().toString(), c.text())).toList(), batch,
                lines.stream().map((l) -> new Line(l.label(), l.qty(), l.unit().setScale(2).toPlainString())).toList(),
                claim.added());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaims {
    public void respond(@Val Sheet sheet, @Val List<Claim> claims, ClaimLogRepository logs, ClaimLockRepository locks,
            ClaimRepository repository, ClaimCommentRepository comments, ClaimLineRepository lines, SettleBatchRepository batches,
            ObjectResponse<List<ClaimResponse>> response) {
        Map<Long, List<ClaimLogLine>> log = logs.findAll(sheet.id());
        Map<Long, String> locked = locks.findAll(sheet.id());
        Set<Long> late = repository.lateEntries(sheet.id());
        Map<Long, LocalDate> reminded = repository.remindedAll(sheet.id());
        Map<Long, String> refs = repository.refs(sheet.id());
        Map<Long, String> tags = repository.tagsAll(sheet.id());
        Map<Long, String> voidReasons = repository.voidReasons(sheet.id());
        Map<Long, Integer> batched = batches.batches(sheet.id());
        Map<Long, List<ClaimComment>> commented = comments.findAll(sheet.id());
        Map<Long, List<ClaimLine>> lined = lines.findAll(sheet.id());
        response.send(claims.stream()
                .map((c) -> ClaimResponse.from(c, log.getOrDefault(c.id(), List.of()), locked.get(c.id()),
                        late.contains(c.id()), reminded.get(c.id()), refs.get(c.id()),
                        tags.get(c.id()), voidReasons.get(c.id()),
                        commented.getOrDefault(c.id(), List.of()), batched.get(c.id()),
                        lined.getOrDefault(c.id(), List.of()))).toList());
    }
}
import type { Claim } from './claims';

// The claim's status log, oldest first: one line per status it has had.
export function ClaimLog({ claim }: { claim: Claim }) {
  return (
    <ol>
      {(claim.log ?? []).map((l, i) => (
        <li key={i} data-testid="claim-log-line">
          {`${l.status} by ${l.by} on ${l.date} due=${l.due}`}
        </li>
      ))}
    </ol>
  );
}
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { ClaimLog } from './ClaimLog';

export const contribution = ClaimRowValues.fill({ order: 40, Component: ClaimLog });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import type { Claim } from './claims';
import { AMOUNT, claimsKey } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';
import { useClaimError } from './claimError';
import { useVoidReasons } from '../voidreasons/voidReasons';

type Action = 'open' | 'review' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle' | 'delete' | 'restore';

const ACTIONS: Array<{ action: Action; label: string }> = [
  { action: 'open', label: 'Open' },
  { action: 'review', label: 'Review' },
  { action: 'settle', label: 'Settle' },
  { action: 'approve', label: 'Approve' },
  { action: 'reject', label: 'Reject' },
  { action: 'void', label: 'Void' },
  { action: 'resettle', label: 'Re-settle' },
  { action: 'delete', label: 'Delete' },
  { action: 'restore', label: 'Restore' },
];

const REFUSED: Partial<Record<Action, string>> = {
  open: ' (your role may not be allowed to open a claim)',
  review: ' (only a steward reviews a claim in REVIEW, which opens it)',
  settle: ' (the user who opened it cannot settle it, one whose due is above the proof threshold needs a proof, and your role may not be allowed to settle)',
  void: ' (your role may not be allowed to void a claim; only a steward voids a settled claim, within 7 days of its settlement; while the sheet has void reasons, choose one)',
  approve: ' (only a steward approves a pending claim, and not the user who opened it; one whose due is above the proof threshold needs a proof)',
  reject: ' (only a steward rejects a pending claim, and a reason is required)',
  resettle: ' (only a steward re-settles a settled claim)',
  delete: ' (only a DRAFT claim not due in a closed period is deleted)',
  restore: ' (a deleted claim is restored only on the day it was deleted)',
};

// A claim's status and the buttons that change it. Every button is shown; the server refuses a
// change the status does not allow, and the refusal shows as the claim's error. A clerk's settle
// above the clerk limit makes the claim PENDING; a reject sends the reason typed beside it. A role
// allowed to reassign (standing rule: a steward) moves a DRAFT, OPEN or PENDING claim to the person chosen beside the
// Move button. A steward re-settles a SETTLED claim, freezing it again at today's figure. An OPEN claim is deferred to the
// date typed beside the Defer button. The Add proof button raises the claim's proofs count by one (not on a
// SETTLED or VOID claim, nor one due by a date in a closed period). The Split button splits the amount typed beside it off an
// OPEN claim into a new OPEN claim of the same person (more than 0.00 and less than the claim's amount). A steward
// re-dates an OPEN or PENDING claim to the date typed beside the Re-date button. While the sheet has void reasons, a void
// sends the reason chosen beside it (none chosen: the server refuses it). Delete sets a DRAFT claim aside as DELETED;
// Restore makes it a DRAFT again, only on the sheet's today it was deleted. An open whose due is above the review threshold
// makes the claim REVIEW; a steward's Review then opens it.
export function ClaimStatus({ claim }: { claim: Claim }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [error, setError] = useClaimError(claim.id);
  const [reason, setReason] = useState('');
  const [voidReason, setVoidReason] = useState('');
  const voidReasons = useVoidReasons().data ?? [];
  const [moveTo, setMoveTo] = useState('');
  const [deferTo, setDeferTo] = useState('');
  const [splitAmount, setSplitAmount] = useState('');
  const [redateTo, setRedateTo] = useState('');
  const others = (usePeople().data ?? []).filter((p) => p.id !== claim.personId);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const change = useMutation({
    mutationFn: (action: Action) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/${action}?user=${encodeURIComponent(user)}`,
        action === 'reject' ? { reason } : action === 'void' ? { reason: voidReason } : {},
      ),
    onSuccess: async (_c, action) => {
      if (action === 'reject') setReason('');
      if (action === 'void') setVoidReason('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: (_e, action) => setError(`This ${claim.status} claim cannot be changed by ${action}${REFUSED[action] ?? ''}.`),
  });

  const reassign = useMutation({
    mutationFn: (personId: number) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/person?user=${encodeURIComponent(user)}`, {
        personId,
      }),
    onSuccess: async () => {
      setMoveTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be moved (only a DRAFT, OPEN or PENDING claim is moved, by a role allowed to reassign).`),
  });

  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/deferral?user=${encodeURIComponent(user)}`, {
        until,
      }),
    onSuccess: async () => {
      setDeferTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be deferred to that date (only an OPEN claim, to a date after today, outside a closed period).`),
  });

  const split = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/split?user=${encodeURIComponent(user)}`, {
        amount,
      }),
    onSuccess: async () => {
      setSplitAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be split by that amount (only an OPEN claim, not deferred nor in a closed period, by more than 0.00 and less than its amount, by a role allowed to open a claim).`,
      ),
  });

  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/date?user=${encodeURIComponent(user)}`, {
        date,
      }),
    onSuccess: async () => {
      setRedateTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be re-dated to that date (only a steward re-dates an OPEN or PENDING claim, not after its person's retirement, nor one due by a date in a closed period).`,
      ),
  });

  const proof = useMutation({
    mutationFn: () =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/proofs?user=${encodeURIComponent(user)}`, {}),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be given a proof (not a SETTLED or VOID claim, nor one in a closed period).`),
  });

  return (
    <>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, label }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
